  class: org.springframework.samples.petclinic.rest.function.owner.RespondWithOwnerCreated
  govern: [ transaction ]
=== PostcodeRegions ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

/**
 * Fixed city-to-region and region-to-postcode-range tables used to validate an owner's
 * postcode against the region derived from the owner's city.
 *
 * <p>Cities: Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD. A city with no known
 * region accepts any 4-digit postcode. Ranges (inclusive): NSW 2000-2099,
 * VIC 3000-3099, QLD 4000-4099.
 */
public final class PostcodeRegions {

    private static final Map<String, String> CITY_REGION = Map.of(
            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    private static final Map<String, int[]> REGION_RANGE = Map.of(
            "NSW", new int[] {2000, 2099},
            "VIC", new int[] {3000, 3099},
            "QLD", new int[] {4000, 4099});

    private PostcodeRegions() {
    }

    /** Canonical region for the city, or null when the city has no known region. */
    public static String regionFor(String city) {
        return CITY_REGION.get(city);
    }

    /**
     * Canonical region whose inclusive postcode range contains {@code postcode}, or null
     * when the postcode is blank, not a number, or in no known range.
     */
    public static String regionForPostcode(String postcode) {
        if (postcode == null || postcode.isBlank()) {
            return null;
        }
        int value;
        try {
            value = Integer.parseInt(postcode.trim());
        }
        catch (NumberFormatException ex) {
            return null;
        }
        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }

    /**
     * True when the 4-digit postcode is valid for the city: valid when the city has no
     * known region, otherwise valid only when the postcode falls within that region's
     * inclusive range.
     */
    static boolean isValid(String city, int postcode) {
        String region = regionFor(city);
        if (region == null) {
            return true; // city with no known region accepts any 4-digit postcode
        }
        int[] range = REGION_RANGE.get(region);
        return range == null || (postcode >= range[0] && postcode <= range[1]);
    }
}
=== AssignOwnerCustomerCode ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashSet;
import java.util.Set;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns a newly created owner a {@code customerCode} formatted {@code '<REGION>-<HASH8>'}:
 * REGION is the region code derived from the owner's postcode (NSW 2000-2099, VIC 3000-3099,
 * QLD 4000-4099, otherwise {@code UNKNOWN}), and HASH8 is the first eight UPPER-case hex
 * characters of the SHA-256 digest over the normalized (E.164) telephone concatenated with the
 * owner's last name. The former per-city sequence number is gone, so the code no longer depends
 * on how many owners already exist. Mutates the {@link Owner} in place so it is persisted and
 * returned with the code, and so every value derived from the customerCode (membership number,
 * check digit, audit line and locality) reflects the new region-and-hash identity.
 *
 * <p>When the computed code collides with an existing owner's {@code customerCode}, it is
 * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
 * makes it unique, so distinct owners always receive distinct customerCodes.
 */
public class AssignOwnerCustomerCode {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String region = PostcodeRegions.regionForPostcode(owner.getPostcode());
        if (region == null) {
            region = "UNKNOWN";
        }
        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
        String base = region + "-" + hash8(telephone + lastName);
        owner.setCustomerCode(deduplicate(base, owner, ownerRepository));
    }

    /**
     * Return {@code base} if no existing owner already holds it, otherwise
     * {@code base + "-" + n} with the smallest {@code n >= 2} that is unused.
     */
    private static String deduplicate(String base, Owner owner, OwnerRepository ownerRepository) {
        Set<String> taken = new HashSet<>();
        for (Owner existing : ownerRepository.findAll()) {
            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
                continue; // never collide with the owner itself
            }
            if (existing.getCustomerCode() != null) {
                taken.add(existing.getCustomerCode());
            }
        }
        if (!taken.contains(base)) {
            return base;
        }
        int n = 2;
        while (taken.contains(base + "-" + n)) {
            n++;
        }
        return base + "-" + n;
    }

    /** First eight UPPER-case hex characters (four bytes) of SHA-256 over the UTF-8 bytes. */
    private static String hash8(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(8);
            for (int i = 0; i < 4; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }
}

